def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    corners=[(0,0,1,1),(0,w-1,1,-1),(h-1,0,-1,1),(h-1,w-1,-1,-1)]
    for r,c,dr,dc in corners:
        if grid[r][c]==4:
            break
    else:
        return out
    for i in range(h):
        for j in range(w):
            if grid[i][j] in (bg,4): continue
            a,b=i+dr,j+dc
            while 0<=a<h and 0<=b<w:
                if grid[a][b]!=bg: break
                out[a][b]=0
                a+=dr;b+=dc
    return out

